import { Api } from './base/api';
export class ApiLarek extends Api {
    constructor(baseUrl, cdn, options) {
        super(baseUrl, options);
        this.cdn = cdn;
    }
    getProductsItem() {
        return this.get('/product')
            .then((data) => {
            return data.items.map((item) => (Object.assign({}, item)));
        });
    }
    orderProductsResponse(order) {
        return this.post('/order', order).then((data) => data);
    }
}
