export class Card extends Component {
    // protected _index?: HTMLElement;
    constructor(container, actions) {
        super(container);
        this._title = ensureElement('.card__title', this.container);
        this._price = ensureElement('.card__price', this.container);
        this._button = container.querySelector('.card__button');
        // this._index = container.querySelector('.basket__item-index')
        if (actions === null || actions === void 0 ? void 0 : actions.onClick) {
            if (this._button) {
                this._button.addEventListener('click', actions.onClick);
            }
            else {
                container.addEventListener('click', actions.onClick);
            }
        }
    }
    set button(value) {
        if (this._button) {
            this._button.textContent = value;
        }
    }
    set id(value) {
        this.container.dataset.id = value;
    }
    set price(value) {
        if (value === null) {
            this.setText(this._price, `Бесценно`);
        }
        else {
            this.setText(this._price, `${value} синапсов`);
        }
    }
    // set index(value: number) {
    //     this.setText(this._index, value);
    // }
    set title(value) {
        this.setText(this._title, value);
    }
}
//данный класс отвечает за отображение карточки на странице
export class OnlyCardOnPage extends Card {
    // _description: HTMLElement;
    constructor(container, actions) {
        super(container, actions);
        this._image = ensureElement('.card__image', container);
        this._category = ensureElement('.card__category', container);
        // this._description = ensureElement<HTMLElement>('.card__text', container);
    }
    set image(value) {
        this.setImage(this._image, value, this.title);
    }
    set category(value) {
        this.setText(this._category, value);
        this.toggleClass(this._category, categoryList[value], true);
    }
}
//класс который отвечает за предпросмтр карточки с детальным ее описанием
export class CardPreview extends OnlyCardOnPage {
    constructor(container, actions) {
        super(container, actions);
        this._description = ensureElement('.card__text', container);
    }
    set description(value) {
        this.setText(this._description, value);
    }
}
export class CardWithIndex extends Card {
    constructor(container, actions) {
        super(container, actions);
        this._index = ensureElement('.basket__item-index', container);
    }
    set index(value) {
        this.setText(this._index, value.toString());
    }
}
