import { Component } from './base/Component';
import { ensureElement, createElement } from '../utils/utils';
export class Basket extends Component {
    constructor(container, events) {
        super(container);
        this.container = container;
        this.events = events;
        this.productListItem = ensureElement('.basket__list', this.container);
        this.totalamount = this.container.querySelector('.basket__price');
        this.button = this.container.querySelector('.basket__button');
        if (this.button) {
            this.button.addEventListener('click', () => {
                events.emit('basket:placeOnOrder');
            });
        }
        this.list = [];
    }
    set list(items) {
        if (items.length) {
            this.productListItem.replaceChildren(...items);
            this.button.removeAttribute('disabled');
        }
        else {
            this.productListItem.replaceChildren(createElement('p', { textContent: 'Корзина пуста' }));
            this.button.setAttribute('disabled', 'disabled');
        }
    }
    set total(value) {
        this.setText(this.totalamount, `${value} синапсов`);
    }
}
